/*
 * Godot C-ABI adapter for the GraalVM-compiled Minecraft input surface.
 * The Java layer does not know about Godot. This adapter owns the GDExtension
 * ABI and forwards plain integer touch data to the Java Native Image library.
 */
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#include "gdextension_interface.h"
#include "minecraft_java.h" /* generated by build.sh from native-image output */

#if defined(_WIN32)
#define GDEXTENSION_EXPORT __declspec(dllexport)
#else
#define GDEXTENSION_EXPORT __attribute__((visibility("default")))
#endif

#define CLASS_NAME "MinecraftTouch"
#define PARENT_CLASS_NAME "RefCounted"

/* gdextension_interface.h returns a generic function pointer. The Godot API
 * explicitly permits an intermediate void-pointer cast for typed interfaces. */
#define LOAD_GODOT_INTERFACE(type, name) ((type)(void *)get_proc_address(name))

typedef struct {
    int placeholder;
} MinecraftTouchInstance;

static GDExtensionInterfaceGetProcAddress godot_get_proc_address;
static GDExtensionClassLibraryPtr godot_library;
static GDExtensionInterfaceStringNameNewWithUtf8Chars string_name_new;
static GDExtensionInterfaceClassdbConstructObject classdb_construct_object;
static GDExtensionInterfaceObjectSetInstance object_set_instance;
static GDExtensionInterfaceClassdbRegisterExtensionClass classdb_register_extension_class;
static GDExtensionInterfaceClassdbRegisterExtensionClassMethod classdb_register_extension_class_method;
static GDExtensionInterfaceGetVariantToTypeConstructor variant_to_int;
static GDExtensionInterfaceGetVariantFromTypeConstructor variant_from_int;
static GDExtensionInterfaceVariantNewNil variant_new_nil;

static graal_isolate_t *java_isolate;
static graal_isolatethread_t *java_main_thread;

static GDExtensionStringNamePtr make_string_name(const char *text) {
    GDExtensionStringNamePtr name = NULL;
    string_name_new(&name, text);
    return name;
}

/* Godot interns StringNames created through the C ABI. They are kept for the
 * process lifetime so all names used by this small extension are created once
 * per registration/lifetime and intentionally not freed here. */
static void free_string_name(GDExtensionStringNamePtr name) {
    (void)name;
}

static graal_isolatethread_t *java_thread(void) {
    if (java_isolate == NULL) {
        return NULL;
    }
    graal_isolatethread_t *thread = graal_get_current_thread(java_isolate);
    if (thread == NULL && graal_attach_thread(java_isolate, &thread) != 0) {
        return NULL;
    }
    return thread;
}

static int java_start(void) {
    if (java_isolate != NULL) {
        return 1;
    }
    if (graal_create_isolate(NULL, &java_isolate, &java_main_thread) != 0) {
        java_isolate = NULL;
        java_main_thread = NULL;
        return 0;
    }
    minecraft_bootstrap(java_main_thread);
    return 1;
}

static void set_call_ok(GDExtensionCallError *error) {
    if (error != NULL) {
        error->error = GDEXTENSION_CALL_OK;
        error->argument = 0;
        error->expected = 0;
    }
}

static void set_argument_error(GDExtensionCallError *error, int argument, int expected) {
    if (error != NULL) {
        error->error = GDEXTENSION_CALL_ERROR_INVALID_ARGUMENT;
        error->argument = argument;
        error->expected = expected;
    }
}

static int64_t variant_int(GDExtensionConstVariantPtr value) {
    int64_t result = 0;
    GDExtensionTypeFromVariantConstructorFunc converter =
            variant_to_int(GDEXTENSION_VARIANT_TYPE_INT);
    converter(&result, (GDExtensionVariantPtr)value);
    return result;
}

static void return_int(GDExtensionVariantPtr result, int64_t value) {
    GDExtensionVariantFromTypeConstructorFunc constructor =
            variant_from_int(GDEXTENSION_VARIANT_TYPE_INT);
    constructor(result, &value);
}

static void return_nil(GDExtensionVariantPtr result) {
    variant_new_nil(result);
}

static GDExtensionObjectPtr minecraft_touch_create(void *class_userdata) {
    (void)class_userdata;
    GDExtensionStringNamePtr class_name = make_string_name(CLASS_NAME);
    GDExtensionObjectPtr object = classdb_construct_object(class_name);
    MinecraftTouchInstance *instance = calloc(1, sizeof(*instance));
    if (object != NULL && instance != NULL) {
        object_set_instance(object, class_name, instance);
    } else {
        free(instance);
    }
    free_string_name(class_name);
    return object;
}

static void minecraft_touch_free(void *class_userdata, GDExtensionClassInstancePtr instance) {
    (void)class_userdata;
    free(instance);
}

static void method_touch_down(void *userdata, GDExtensionClassInstancePtr instance,
        const GDExtensionConstVariantPtr *args, GDExtensionInt argument_count,
        GDExtensionVariantPtr result, GDExtensionCallError *error) {
    (void)userdata;
    (void)instance;
    if (argument_count != 5) {
        set_argument_error(error, (int)argument_count, 5);
        return_nil(result);
        return;
    }
    graal_isolatethread_t *thread = java_thread();
    if (thread != NULL) {
        minecraft_touch_down(thread, (int)variant_int(args[0]), (int)variant_int(args[1]),
                (int)variant_int(args[2]), (int)variant_int(args[3]), (int)variant_int(args[4]));
    }
    set_call_ok(error);
    return_nil(result);
}

