static void ptrcall_touch_down(void *userdata, GDExtensionClassInstancePtr instance,
        const GDExtensionConstTypePtr *args, GDExtensionTypePtr result) {
    (void)userdata; (void)instance; (void)result;
    graal_isolatethread_t *thread = java_thread();
    if (thread != NULL) {
        minecraft_touch_down(thread, (int)*(const int64_t *)args[0], (int)*(const int64_t *)args[1],
                (int)*(const int64_t *)args[2], (int)*(const int64_t *)args[3], (int)*(const int64_t *)args[4]);
    }
}

